mapper.update:
UPDATE TB_SAGA_INSTANCE
SET
	STATUS = #{STATUS}
	, CURRENT_STEP = #{CURRENT_STEP}
WHERE 1=1
	AND SAGA_ID = #{SAGA_ID}

UPDATE TB_SAGA_STEP_HISTORY
SET
	COMPENSATE_RESULT = #{RESULT}
	, COMPENSATE_ERROR_MSG = #{ERROR_MSG}
	, COMPENSATED_DT = NOW()
WHERE 1=1
	AND SAGA_ID = #{SAGA_ID}
	AND STEP_NAME = #{STEP_NAME}
	AND RESULT = 'SUCCESS'
